 if(!s.identity||String(user.id)!==String(s.identity.id))throw staleIdentity();
 if(wasBanned||wasPending){s.accountBanned=null;s.accountAccessPending=null;accountEpoch++;}
 const previous=s.user,guildChanged=String(previous?.guildId||'')!==String(user.guildId||''),guildRoleChanged=(previous?.guildRole||'')!==(user.guildRole||''),roleChanged=(previous?.isAdmin===true)!==(user.isAdmin===true)||(previous?.isStaff===true)!==(user.isStaff===true&&user.isAdmin!==true),wasAdminTab=['admin','recent-logins'].includes(s.tab);
 const currentAvatar=global.SengokuAvatar?.resolve?.(user),currentGuildIcon=user.guildId?global.SengokuAllianceIcon?.resolve?.({id:user.guildId,name:user.guildName,iconVersion:user.guildIconVersion}):null;s.user={...user,...(!Object.hasOwn(user,'commander')&&previous?.id===user.id&&Object.hasOwn(previous,'commander')?{commander:previous.commander}:{}),...(currentAvatar?{avatarVersion:currentAvatar.avatarVersion}:{}),...(currentGuildIcon?{guildIconVersion:currentGuildIcon.iconVersion}:{}),isBanned:false,isAdmin:user.isAdmin===true,isStaff:user.isStaff===true&&user.isAdmin!==true};global.SengokuPublicCourt?.update?.({user:s.user});if(guildChanged||guildRoleChanged){clearGuildData({resetSection:guildChanged});if(s.open&&s.tab==='guild')render();}if(!fromSync)applyRoleAccess(s.user);
 if(roleChanged){clearAdminData();global.SengokuModeration?.refreshIdentity?.();global.SengokuPremiumRuntime?.refreshIdentity?.();global.SengokuEvents?.refreshAccess?.();global.SengokuShogunate?.refreshAccess?.();global.SengokuCourt?.refreshAccess?.();global.SengokuVoice?.refreshAccess?.();global.SengokuProgress?.refresh?.();global.SengokuAlliance?.refreshAccess?.();global.SengokuConquest?.refreshAccess?.();global.SengokuNotifications?.refreshAccess?.();if(wasAdminTab&&!hasAdminChat())s.tab='profile';renderTabs();if(body&&(s.open||wasAdminTab)){clearConfirm();render();}if(s.open&&s.tab==='recent-logins'&&hasAdminChat())loadRecentLogins();}
 else if((!previous||wasBanned||wasPending)&&s.open&&!s.confirm)render();if(!previous||wasBanned||wasPending||previous.name!==s.user.name)global.SengokuPremiumRuntime?.refreshIdentity?.();global.SengokuEvents?.refreshAccess?.();global.SengokuShogunate?.refreshAccess?.();global.SengokuCourt?.refreshAccess?.();global.SengokuVoice?.refreshAccess?.();global.SengokuProgress?.refresh?.();global.SengokuAlliance?.refreshAccess?.();global.SengokuConquest?.refreshAccess?.();global.SengokuNotifications?.refreshAccess?.();applyPlayerEvaluations([{playerId:s.user.id,name:s.user.name,avatarVersion:s.user.avatarVersion||null,evaluation:s.user.evaluation}]);if(!previous||guildChanged||wasBanned||wasPending){global.SengokuResidency?.refreshIdentity?.();global.SengokuLetters?.refreshIdentity?.();global.SengokuTrade?.refreshIdentity?.();global.SengokuTroopGarrisons?.refreshIdentity?.();}refreshProfileAvatar();const card=s.tab==='profile'&&$('[data-own-commander]');if(card)global.SengokuLordProfile?.paintCommander?.(card,s.user.commander,s.user.id);refreshGuildIcon();header();global.SengokuResidency?.refreshIdentity?.();
