const troopCapacityText=state=>'兵士：所持 '+num(state.balances.troops)+'人 · 輸入・返還の受入枠 '+(state.troopTransportCapacity===null?'確認中':'あと'+num(Math.max(0,state.troopTransportCapacity-(state.balances.troops??0)))+'人')+'（拠点容量とは別枠）';
